input.command:
try { $xl = New-Object -ComObject Excel.Application -ErrorAction Stop } catch { "NO_EXCEL: $($_.Exception.Message)"; exit 0 }
$xl.Visible = $false; $xl.DisplayAlerts = $false
try {
  $wb = $xl.Workbooks.Open("C:\dev\ExecTrace\SPEC_checklist.xlsx")
  $xl.CalculateFull()
  $s = $wb.Worksheets.Item("Summary")
  foreach ($r in 4..7 + 10..19) { (1..7 | ForEach-Object { $s.Cells.Item($r, $_).Text }) -join " | " }
  $errs = 0
  foreach ($c in $s.UsedRange.Cells) { if ($xl.WorksheetFunction.IsError($c)) { $errs++ } }
  "ERRORS: $errs"
  $wb.Save(); $wb.Close($false)
} finally { $xl.Quit(); [void][Runtime.InteropServices.Marshal]::ReleaseComObject($xl) }

